+    return res;
+  } catch (err) {
+    await db.exec('rollback to savepoint sp_actor;');
+    throw err;
+  } finally {
+    try {
+      await db.exec(`reset role; select set_config('request.jwt.claim.sub', '', true);`);
+    } catch {
